import {disabilityPrevalenceData as data} from './planning-disability-prevalence-data.js';
export const disabilityPrevalenceDefinitions={
 disabilityPrevalence:{title:'Change an invented age mix while keeping published subgroup rates fixed',fields:[
  ['olderShareA','Invented share aged 65+ in population A (%)',20,0,100,5],
  ['olderShareB','Invented share aged 65+ in population B (%)',40,0,100,5]
 ]}
};
export function disabilityMix(olderShare) {
 const older=olderShare/100,adultRate=data.ageGroups[1]['2022'].value/100,olderRate=data.ageGroups[2]['2022'].value/100;
 const contributions=[(1-older)*adultRate,older*olderRate];
 return {older,adult:1-older,contributions,total:contributions[0]+contributions[1]};
}
export function disabilityPrevalenceResult(kind,input) {
 if(kind!=='disabilityPrevalence')throw Error('Unknown disability-prevalence topic.');
 const a=disabilityMix(input.olderShareA),b=disabilityMix(input.olderShareB),source={source:data.url,sourceLabel:data.title};
 return {metrics:[['Illustrated aggregate in invented population A · ages 25+',a.total,'percent'],['Illustrated aggregate in invented population B · ages 25+',b.total,'percent'],['Illustrated difference B minus A · percentage points',b.total-a.total,'pp']],note:'The first two figures use a dated public extract of all-gender Canadian Survey on Disability estimates for 2017 and 2022, from Statistics Canada Table 1.1.A modified 28 May 2024 and reviewed 25 October 2026. Source rates are published percent; charts store them as fractions. These are estimates of disability prevalence for the survey’s covered population, not annual incidence, a lifetime probability, an insurance-claim probability or a measure of inability to work. The source’s 95% confidence intervals are retained in the first figure and its data table. The controls affect only a separate arithmetic illustration: two invented populations containing ages 25–64 and 65+, with fixed 2022 subgroup estimates and chosen age shares. Ages 15–24 are excluded from that illustration. Neither selected share is an observed national age mix. The last two charts and headline aggregates are derived scenarios, with no confidence interval or forecast inferred from subgroup bounds. Changing a share does not alter any source estimate.',charts:[
  {id:'disability-prevalence-estimates',type:'intervalbar',title:'Published prevalence estimates by age group and survey year',unit:'percent',unitLabel:'Percent within the stated age group · all genders · published 95% confidence intervals',...source,evidence:'Official survey estimates · published 95% confidence intervals',rows:data.ageGroups.flatMap(r=>[2017,2022].map(year=>({label:r.label+' · '+year,value:r[year].value/100,lower:r[year].lower/100,upper:r[year].upper/100}))),note:'Each row uses its own age-group denominator. The six rows are not six parts of one population to add together. Whiskers retain the source’s asymmetric 95% confidence bounds for each point estimate. They describe survey estimation uncertainty; they are not a range of personal health outcomes or future claim probabilities. These two survey cycles do not trace one age group’s individual members as they grow older.'},
  {id:'disability-prevalence-point-changes',type:'bar',title:'Change in each age-group estimate from 2017 to 2022',unit:'pp',unitLabel:'Percentage-point change · 2022 estimate minus 2017 estimate',...source,evidence:'Arithmetic differences of published survey estimates',rows:data.ageGroups.map(r=>({label:r.label,value:(r['2022'].value-r['2017'].value)/100})),note:'A percentage-point difference subtracts two percentage levels. It is not their relative percentage increase. Statistics Canada marks all three selected all-gender age-group comparisons as significantly different from 2017 at p < 0.05 in this source. The table does not supply confidence bounds for these differences; none are manufactured by subtracting the individual interval endpoints. The underlying estimate bounds remain visible in the first figure.'},
  {id:'disability-prevalence-invented-mix',type:'stackbar',title:'Illustrated aggregate contributions under two invented age mixes',unit:'percent',unitLabel:'Contribution to the illustrated aggregate prevalence · invented populations aged 25+',...source,evidence:'Arithmetic illustration · fixed official rates and invented weights',seriesNames:['Ages 25–64 contribution','Ages 65+ contribution'],rows:[{label:'Population A · '+input.olderShareA+'% aged 65+',values:a.contributions},{label:'Population B · '+input.olderShareB+'% aged 65+',values:b.contributions}],note:'Each contribution equals an invented population share multiplied by its fixed 2022 age-group estimate: 24.1% for ages 25–64 and 40.4% for ages 65+. Stacked contributions sum to the illustrated aggregate. The segment heights are contributions to that aggregate, not the population shares themselves. These two groups cover the illustration’s ages-25+ universe; youth are not silently assigned a zero rate. This is not a reconstruction of Canada’s 15+ estimate, an observed cohort or an age-standardized official result. No aggregate confidence interval is calculated.'},
  {id:'disability-prevalence-mix-sensitivity',type:'line',title:'Illustrated aggregate as the invented 65+ population share changes',unit:'percent',unitLabel:'Illustrated aggregate prevalence · fixed 2022 subgroup estimates',xLabel:'Invented share aged 65+ in an ages-25+ population (%)',...source,evidence:'Arithmetic illustration · fixed official rates and invented weights',series:[{name:'Weighted aggregate using unchanged subgroup estimates',rows:Array.from({length:21},(_,i)=>({x:i*5,value:disabilityMix(i*5).total}))}],note:'The endpoints are the fixed 24.1% and 40.4% subgroup estimates. Every interior point is a weighted mean under the labelled invented composition. The horizontal axis is a population share, not age or time. The line does not predict how any individual’s condition changes. The two controls choose points on this unchanged comparison curve and update the contribution bars and headline illustrations; the historical survey figures remain fixed.'}
 ]};
}
